    explanation: "Rolle's Theorem states: if f is continuous on [a,b], differentiable on (a,b), and f(a) = f(b), then there exists c in (a,b) with f'(c) = 0. This is the MVT with f(a) = f(b), making the right side (f(b)-f(a))/(b-a) = 0. Rolle's Theorem is used to prove the MVT itself.",
    explanationChinese: "罗尔定理指出：如果 f 在 [a,b] 上连续，在 (a,b) 上可导，且 f(a) = f(b)，则存在 c ∈ (a,b) 使 f'(c) = 0。这是中值定理在 f(a) = f(b) 时的情况，使右边 (f(b)-f(a))/(b-a) = 0。罗尔定理用于证明中值定理本身。",
